/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isStringArray = require( '@stdlib/assert/is-string-array' );
var format = require( '@stdlib/string/format' );

/**
* Validate the array.
*
* @private
* @param {Collection<string>} value - array of axises data
* @throws {TypeError}
*/
function validate( value ) {
	if ( !isStringArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a Array of string. Value: `%s`.', 'axis-label-format', value ) );
	}
	if ( value.length !== 4 ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a Array of length 4. Value: `%s`.', 'axis-label-format', value ) );
	}
}


// MAIN //

/**
* Sets the axis label formate.
*
* @private
* @param {Array} value - Array of string represent the formate string for axis labels.
* @throws {TypeError} must be array of string with length 4.
*/
function set( value ) {
	var isChange = false;
	var i;

	validate( value );
	for ( i = 0; i < 4; i++ ) {
		if ( this._axisDataObjs[ i ].labelFormate !== value ) {
			this._axisDataObjs[ i ].labelFormate = value[ i ];
			isChange = true;
		}
	}
	if ( isChange && !this._quite ) {
		this.emit( 'change' );
	}
}


// EXPORTS //

module.exports = set;
